use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    /// Byte offset of the next unread byte; never past the end of `src`.
    pos: usize,
    state: State,
}

/// What the tokenizer expects to find at `pos`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Optional separators, then a timestamp, a key or a word.
    Token,
    /// The value directly after a key's `=`.
    Value,
    /// An error has been reported; the stream is over.
    Failed,
}

type LexResult<'a> = Result<Token<'a>, LexError>;

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Token }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = LexResult<'a>;

    fn next(&mut self) -> Option<Self::Item> {
        let result = match self.state {
            State::Token => self.token()?,
            State::Value => self.value(),
            State::Failed => return None,
        };
        if result.is_err() {
            self.fail();
        }
        Some(result)
    }
}

impl<'a> Tokens<'a> {
    /// Reads the next timestamp, key or word, or returns `None` at the end of the line.
    fn token(&mut self) -> Option<LexResult<'a>> {
        self.skip_separators();
        let start = self.pos;
        let token = match *self.bytes().get(start)? {
            b'[' => self.timestamp(start),
            b'"' => Err(LexError::UnexpectedQuote { pos: start }),
            b'=' => Err(LexError::EmptyKey { pos: start }),
            _ => self.key_or_word(start),
