            Some(quote) if bytes[quote] == b'"' => Err(LexError::UnexpectedQuote { pos: quote }),
            Some(end) => Ok(end),
            None => Ok(bytes.len()),
        }
    }

    /// Ends a token whose last byte is at `last`. The byte after it must be a separator or the end of the line.
    fn finish_token_at(&mut self, last: usize) -> Result<(), LexError> {
