        let skipped = self.bytes()[self.pos..].iter().take_while(|&&b| is_separator(b)).count();
        self.pos += skipped;
    }

    fn fail(&mut self) {
        self.state = State::Failed;
        self.pos = self.src.len();
    }

    fn bytes(&self) -> &'a [u8] {
        self.src.as_bytes()
    }
}

