fn random_line(rng: &mut Rng) -> String {
    let len = (rng.next() % 16) as usize;
    (0..len).map(|_| PIECES[(rng.next() % PIECES.len() as u64) as usize]).collect()
}

fn poll<T: std::fmt::Debug>(mut next: impl FnMut() -> Option<T>) -> Vec<String> {
    (0..40).map(|_| format!("{:?}", next())).collect() // keeps polling past None / errors
}

fn bench_lines() -> Vec<String> {
    let mut rng = Rng(42);
    (0..2_000_000)
        .map(|i| {
            let r = rng.next();
            match i % 4 {
                0 => format!("[2024-05-01T12:00:{:02}Z] level=info msg=\"disk {}% full \\\"x\\\"\" user=ann retries= done", r % 60, r % 100),
                1 => format!("started worker-{} ok\tpid={} path=/var/log/a{}.log", r % 9, r, r % 7),
                2 => "[2024-05-01T12:00:00Z] k1=v1 k2=\"quoted value with spaces\" k3=v3 k4=v4 k5=\"a\\tb\" word".to_string(),
                _ => format!("level=warn msg=\"unterminated {r}"),
            }
        })
        .collect()
}

fn main() {
    println!("sample: {:?}", bench_lines()[0]);
    let mut rng = Rng(0x9E3779B97F4A7C15);
    for i in 0..3_000_000u32 {
        let line = random_line(&mut rng);
        let mut a = old::Tokens::new(&line);
        let mut b = logscan::tokenize(&line);
        if poll(|| a.next()) != poll(|| b.next()) {
            panic!("mismatch #{i} on {line:?}");
        }
    }
    println!("3M random lines: identical");

    let lines = bench_lines();
    let (mut best_old, mut best_new) = (Duration::MAX, Duration::MAX);
    for _ in 0..15 {
        let t = Instant::now();
        let mut c = 0usize;
        for l in &lines {
            for tok in old::Tokens::new(l) {
                c += std::hint::black_box(tok).is_ok() as usize;
            }
        }
        best_old = best_old.min(t.elapsed());
        let t = Instant::now();
        let mut d = 0usize;
        for l in &lines {
            for tok in logscan::tokenize(l) {
                d += std::hint::black_box(tok).is_ok() as usize;
            }
        }
        best_new = best_new.min(t.elapsed());
        assert_eq!(c, d);
    }
    println!("best of 15: old {best_old:?}  new {best_new:?}");
}
